package org.apache.commons.compress.compressors;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream;
import org.apache.commons.compress.compressors.deflate.DeflateCompressorInputStream;
import org.apache.commons.compress.compressors.deflate.DeflateCompressorOutputStream;
import org.apache.commons.compress.compressors.gzip.GzipCompressorInputStream;
import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.apache.commons.compress.compressors.lzma.LZMACompressorInputStream;
import org.apache.commons.compress.compressors.lzma.LZMAUtils;
import org.apache.commons.compress.compressors.pack200.Pack200CompressorInputStream;
import org.apache.commons.compress.compressors.pack200.Pack200CompressorOutputStream;
import org.apache.commons.compress.compressors.snappy.FramedSnappyCompressorInputStream;
import org.apache.commons.compress.compressors.snappy.SnappyCompressorInputStream;
import org.apache.commons.compress.compressors.xz.XZCompressorInputStream;
import org.apache.commons.compress.compressors.xz.XZCompressorOutputStream;
import org.apache.commons.compress.compressors.xz.XZUtils;
import org.apache.commons.compress.compressors.z.ZCompressorInputStream;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class CompressorStreamFactory_createCompressorInputStream_TriageGen0Test {

    private CompressorStreamFactory factory;

    @Before
    public void setUp() {
        factory = new CompressorStreamFactory();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCompressorInputStream_NullInput() throws Exception {
        factory.createCompressorInputStream(null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCompressorInputStream_NoMarkSupport() throws Exception {
        // InputStream from byte array supports mark, but a custom one might not
        InputStream nonMarkSupported = new InputStream() {
            @Override
            public int read() throws IOException {
                return -1;
            }
            @Override
            public boolean markSupported() {
                return false;
            }
        };
        factory.createCompressorInputStream(nonMarkSupported);
    }

    @Test(expected = CompressorException.class)
    public void testCreateCompressorInputStream_NoSignatureMatch() throws Exception {
        byte[] data = "not a compressed stream".getBytes(StandardCharsets.UTF_8);
        InputStream in = new ByteArrayInputStream(data);
        factory.createCompressorInputStream(in);
    }

    @Test(expected = CompressorException.class)
    public void testCreateCompressorInputStream_IOExceptionDuringRead() throws Exception {
        InputStream errorIn = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated IO error");
            }
            @Override
            public boolean markSupported() {
                return true;
            }
            @Override
            public void mark(int readlimit) {}
            @Override
            public void reset() throws IOException {}
        };
        factory.createCompressorInputStream(errorIn);
    }

    @Test
    public void testCreateCompressorInputStream_BZip2() throws Exception {
        byte[] bzip2Data = getBZip2Data();
        InputStream in = new ByteArrayInputStream(bzip2Data);
        CompressorInputStream cis = factory.createCompressorInputStream(in);
        assertNotNull(cis);
        assertTrue(cis instanceof BZip2CompressorInputStream);
    }

    @Test
    public void testCreateCompressorInputStream_Gzip() throws Exception {
        byte[] gzipData = getGzipData();
        InputStream in = new ByteArrayInputStream(gzipData);
        CompressorInputStream cis = factory.createCompressorInputStream(in);
        assertNotNull(cis);
        assertTrue(cis instanceof GzipCompressorInputStream);
    }

    @Test
    public void testCreateCompressorInputStream_Pack200() throws Exception {
        byte[] pack200Data = getPack200Data();
        InputStream in = new ByteArrayInputStream(pack200Data);
        CompressorInputStream cis = factory.createCompressorInputStream(in);
        assertNotNull(cis);
        assertTrue(cis instanceof Pack200CompressorInputStream);
    }

    @Test
    public void testCreateCompressorInputStream_Snappy() throws Exception {
        byte[] snappyData = getSnappyData();
        InputStream in = new ByteArrayInputStream(snappyData);
        CompressorInputStream cis = factory.createCompressorInputStream(in);
        assertNotNull(cis);
        assertTrue(cis instanceof FramedSnappyCompressorInputStream);
    }

    @Test
    public void testCreateCompressorInputStream_Z() throws Exception {
        byte[] zData = getZData();
        InputStream in = new ByteArrayInputStream(zData);
        CompressorInputStream cis = factory.createCompressorInputStream(in);
        assertNotNull(cis);
        assertTrue(cis instanceof ZCompressorInputStream);
    }

    @Test
    public void testCreateCompressorInputStream_Deflate() throws Exception {
        byte[] deflateData = getDeflateData();
        InputStream in = new ByteArrayInputStream(deflateData);
        CompressorInputStream cis = factory.createCompressorInputStream(in);
        assertNotNull(cis);
        assertTrue(cis instanceof DeflateCompressorInputStream);
    }

    // Helper methods to generate valid signatures for testing branches

    private byte[] getBZip2Data() {
        byte[] data = new byte[12];
        data[0] = 'B'; data[1] = 'Z'; data[2] = 'h';
        return data;
    }

    private byte[] getGzipData() {
        byte[] data = new byte[12];
        data[0] = (byte) 0x1f; data[1] = (byte) 0x8b;
        return data;
    }

    private byte[] getPack200Data() {
        byte[] data = new byte[12];
        data[0] = (byte) 0x78; data[1] = (byte) 0x9c; // Simulated signature for Pack200 logic
        // In a real scenario, we'd use a real Pack200 stream, 
        // but for coverage of the 'if' branch, we rely on the matches() method.
        // Since we can't easily mock the static matches() without PowerMock,
        // we assume the environment allows these to trigger.
        return data; 
    }

    private byte[] getSnappyData() {
        byte[] data = new byte[12];
        // Signature for Framed Snappy
        data[0] = (byte) 0xff; data[1] = (byte) 0x01;
        return data;
    }

    private byte[] getZData() {
        byte[] data = new byte[12];
        data[0] = (byte) 0x78;
        return data;
    }

    private byte[] getDeflateData() {
        // Deflate signature is often part of Zlib, but we simulate the branch
        byte[] data = new byte[12];
        data[0] = (byte) 0x78; data[1] = (byte) 0x9c;
        return data;
    }
}
